def estatNotas(notas):
    maior = notas[0]
    menor = notas[0]
    soma = 0.0
    for i in range(len(notas)):
        if notas[i] > maior:
            maior = notas[i]
        if notas[i] < menor:
            menor = notas[i]
        soma += notas[i]
    return maior, menor, soma / len(notas)

def acimaMedia(notas, corte):
    indices = []
    for i in range(len(notas)):
        if notas[i] > corte:
            indices.append(i)
    return indices

def exameEspecial(notas):
    indices = []
    for i in range(len(notas)):
        if notas[i] >= 3.0 and notas[i] < 6.0:
            indices.append(i)
    return indices

